begin;
truncate public.couples,public.profiles,public.operation_receipts cascade;
set local search_path=public,extensions;select no_plan();
insert into auth.users(id,email,email_confirmed_at) values('00000000-0000-4000-8000-000000000067','settings-first@example.test',now()),('00000000-0000-4000-8000-000000000068','settings-partner@example.test',now());
insert into public.profiles(user_id,display_name) values('00000000-0000-4000-8000-000000000067','First'),('00000000-0000-4000-8000-000000000068','Partner');
insert into public.couples(id,name,start_date) values('10000000-0000-4000-8000-000000000067','Our Story','2024-01-01');
insert into public.memberships(couple_id,user_id,slot) values('10000000-0000-4000-8000-000000000067','00000000-0000-4000-8000-000000000067',1),('10000000-0000-4000-8000-000000000067','00000000-0000-4000-8000-000000000068',2);
insert into public.photos(id,couple_id,uploader_id,storage_path,event_date,bytes,format,width,height) values('30000000-0000-4000-8000-000000000067','10000000-0000-4000-8000-000000000067','00000000-0000-4000-8000-000000000067','test/own.jpg','2024-01-01',100,'image/jpeg',24,16),('30000000-0000-4000-8000-000000000068','10000000-0000-4000-8000-000000000067','00000000-0000-4000-8000-000000000068','test/partner.jpg','2024-01-01',100,'image/jpeg',24,16);
create function pg_temp.settings(command text,payload jsonb,actor uuid default '00000000-0000-4000-8000-000000000067',op uuid default gen_random_uuid()) returns jsonb language sql as $$select public.commit_mutation(actor,command,payload,op,'settings-test',now()+interval '1 day')$$;
select pg_temp.settings('profile.update','{"expected_version":1,"display_name":"Tên 💗","avatar_photo_id":"30000000-0000-4000-8000-000000000067"}',op=>'50000000-0000-4000-8000-000000000067');
select is((select display_name from public.profiles where user_id='00000000-0000-4000-8000-000000000067'),'Tên 💗','Own profile updated');
select is((select display_name from public.profiles where user_id='00000000-0000-4000-8000-000000000068'),'Partner','Partner profile untouched');
select is((select count(*)::integer from public.notifications),1,'Profile change notifies once');
select pg_temp.settings('profile.update','{"expected_version":1,"display_name":"Tên 💗","avatar_photo_id":"30000000-0000-4000-8000-000000000067"}',op=>'50000000-0000-4000-8000-000000000067');
select is((select count(*)::integer from public.notifications),1,'Replay emits no duplicate');
select pg_temp.settings('profile.update','{"expected_version":2,"display_name":"Tên 💗","avatar_photo_id":"30000000-0000-4000-8000-000000000067"}');
select is((select version from public.profiles where user_id='00000000-0000-4000-8000-000000000067'),2,'No-op keeps profile version');
select is((select count(*)::integer from public.notifications),1,'No-op emits no event');
select throws_ok($$select pg_temp.settings('profile.update','{"expected_version":1,"display_name":"Stale"}')$$,'P0001','CONFLICT','Stale profile rejected');
select throws_ok($$select pg_temp.settings('profile.update','{"expected_version":2,"display_name":"x","avatar_photo_id":"30000000-0000-4000-8000-000000000068"}')$$,'P0001','INVALID_REFERENCE','Partner upload cannot be own avatar');
select throws_ok($$select pg_temp.settings('profile.update','{"expected_version":1,"display_name":"forged"}','00000000-0000-4000-8000-000000000069')$$,'P0001','ACCESS_DENIED','Outsider cannot mutate');
select pg_temp.settings('couple.update','{"expected_version":1,"name":"Nhà của mình","featured_photo_id":"30000000-0000-4000-8000-000000000067"}','00000000-0000-4000-8000-000000000068');
select is((select name from public.couples),'Nhà của mình','Partner edits shared name');
select is((select featured_photo_id::text from public.couples),'30000000-0000-4000-8000-000000000067','Either partner selects same-space ready photo');
select pg_temp.settings('couple.update','{"expected_version":2,"name":"Nhà của mình","featured_photo_id":"30000000-0000-4000-8000-000000000067"}');
select is((select version from public.couples),2,'Shared no-op keeps version');
select throws_ok($$select pg_temp.settings('couple.update','{"expected_version":1,"name":"Stale"}')$$,'P0001','CONFLICT','Stale shared update denied');
select throws_ok($$select pg_temp.settings('couple.update','{"expected_version":2,"featured_photo_id":"30000000-0000-4000-8000-000000000069"}')$$,'P0001','INVALID_REFERENCE','Unknown/foreign featured reference denied');
update public.photos set state='deleting' where id='30000000-0000-4000-8000-000000000068';
select throws_ok($$select pg_temp.settings('couple.update','{"expected_version":2,"featured_photo_id":"30000000-0000-4000-8000-000000000068"}')$$,'P0001','INVALID_REFERENCE','Deleting photo cannot be revived');
select lives_ok($$select pg_temp.settings('profile.update',jsonb_build_object('expected_version',2,'display_name',repeat('💗',100),'avatar_photo_id',null))$$,'100 code points accepted');
select throws_ok($$select pg_temp.settings('profile.update',jsonb_build_object('expected_version',3,'display_name',repeat('💗',101)))$$,'23514',null,'Overlong profile rejected');
select ok(not has_table_privilege('authenticated','public.profiles','UPDATE'),'Direct profile write denied');
select ok(not has_table_privilege('authenticated','public.couples','UPDATE'),'Direct shared write denied');
select pg_temp.settings('couple.update','{"expected_version":2,"start_date":"2024-02-29","first_meeting_date":"2023-01-01","timezone":"Asia/Ho_Chi_Minh"}');
select is((select start_date::text from public.couples),'2024-02-29','Existing relationship update compatible');
select is((select name from public.couples),'Nhà của mình','Relationship update preserves name');
select is((select featured_photo_id::text from public.couples),'30000000-0000-4000-8000-000000000067','Relationship update preserves image');
select * from finish();rollback;
